package vn.edu.eaut.lab7.listener; import jakarta.servlet.*; import jakarta.servlet.annotation.WebListener; import java.time.LocalDateTime; @WebListener public class AppListener implements ServletContextListener { public void contextInitialized(ServletContextEvent e){System.out.println("Lab07 started: "+LocalDateTime.now());} public void contextDestroyed(ServletContextEvent e){System.out.println("Lab07 stopped: "+LocalDateTime.now());}}